const BLUE='#2563eb',RED='#dc3545', isColor=c=>typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c);
function teamColor(id,g=game()){return isColor(team(id)?.color)?team(id).color:g?.away===id?RED:BLUE}
function colorText(c){const n=parseInt(c.slice(1),16);return (((n>>16)&255)*.299+((n>>8)&255)*.587+(n&255)*.114)>155?'#102723':'#ffffff'}
function opposingTeam(g,id){return id===g.home?g.away:g.home}
function keeperValue(g,id){return g.keepers?.[id]??''}
function keeperLabel(id,value){return value==='empty'?'Leeres Tor':value==='?'?'Unbekannt':value?`#${value} ${playerName(id,value)}`:'Bitte auswählen'}
function keeperOptions(id,current){const players=team(id)?.players||[];return `<option value="">Bitte auswählen</option>${players.map(p=>`<option value="${p.number}" ${current===p.number?'selected':''}>#${p.number} ${esc(p.name)}</option>`).join('')}${current&&!['?','empty'].includes(current)&&!players.some(p=>p.number===current)?`<option selected value="${esc(current)}">#${esc(current)} (früherer Kader)</option>`:''}<option value="?" ${current==='?'?'selected':''}>Torhüter unbekannt</option><option value="empty" ${current==='empty'?'selected':''}>Leeres Tor</option>`}
function keepersReady(g){return Boolean(keeperValue(g,g.home)&&keeperValue(g,g.away))}
function keeperDialog(g){modal(`<form id="keeper-form"><div class="eyebrow">Vor dem Anpfiff</div><h2>Torhüter auswählen</h2><p class="muted" style="margin-top:12px;line-height:1.6">Für jede Mannschaft bleibt die Auswahl in diesem Spiel gespeichert, bis du sie änderst. Jeder Wurf behält seinen damaligen Torhüter.</p><div class="formgrid">${[g.home,g.away].map(id=>`<label><span class="color-dot" style="background:${teamColor(id,g)}"></span> ${esc(teamName(id))}<select required name="${id}">${keeperOptions(id,keeperValue(g,id))}</select></label>`).join('')}</div><label>Minuten pro Halbzeit<select name="halfMinutes">${[20,25,30].map(n=>`<option value="${n}" ${(g.halfMinutes||30)===n?'selected':''}>${n} Minuten</option>`).join('')}</select></label><div class="dialog-actions"><button type="button" data-close>Später</button><button class="primary">Auswahl speichern</button></div></form>`);$('#keeper-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);g.keepers={[g.home]:fd.get(g.home),[g.away]:fd.get(g.away)};g.halfMinutes=Number(fd.get("halfMinutes"));persist();$('#dialog').close();render();toast('Torhüter gespeichert')};}
const selectGameBeforeKeepers=selectGame;
selectGame=function(id){selectGameBeforeKeepers(id);const g=game();if(g&&!keepersReady(g))keeperDialog(g)};
teamDialog=function(id){const t=team(id);modal(`<form id="team-form"><div class="eyebrow">Mannschaft verwalten</div><h2 style="margin-top:8px">${t?'Kader bearbeiten':'Neue Mannschaft'}</h2><label style="margin-top:20px">Mannschaftsname<input name="name" required maxlength="70" value="${esc(t?.name||'')}" placeholder="z. B. TSV Heimteam"></label><div class="formgrid"><label>Mannschaftsfarbe<select name="colorMode" id="color-mode"><option value="auto" ${!isColor(t?.color)?'selected':''}>Automatisch: Heim Blau, Gast Rot</option><option value="custom" ${isColor(t?.color)?'selected':''}>Eigene Farbe</option></select></label><label>Eigene Farbe<input type="color" name="color" id="team-color" value="${isColor(t?.color)?t.color:BLUE}" ${!isColor(t?.color)?'disabled':''}></label></div><label>Spieler: eine Zeile pro Spieler<textarea name="roster" placeholder="7 Max Mustermann&#10;12 Alex Beispiel">${esc(t?.players.map(p=>p.number+' '+p.name).join('\n')||'')}</textarea></label><p class="muted">Trikotnummer (0–99), dann optional der Name. Feste Nummern bleiben über alle Spiele zugeordnet.</p><div class="dialog-actions"><button type="button" data-close>Abbrechen</button><button class="primary">Speichern</button></div></form>`);$('#color-mode').onchange=e=>{$('#team-color').disabled=e.target.value==='auto'};$('#team-form').onsubmit=e=>{e.preventDefault();try{const fd=new FormData(e.target),name=fd.get('name').trim();if(!name)return;const players=parseRoster(fd.get('roster')),color=fd.get('colorMode')==='custom'?fd.get('color'):null;if(t){t.name=name;t.players=players;t.color=color}else db.teams.push({id:uid(),name,players,color});persist();$('#dialog').close();render()}catch(err){toast(err.message)}}};
function parseRoster(text){const players=[];for(const line of text.split('\n').map(l=>l.trim()).filter(Boolean)){const m=line.match(/^(\d{1,2})(?:\s+(.*))?$/);if(!m)throw Error('Bitte jede Zeile mit einer Trikotnummer beginnen.');const number=String(Number(m[1]));if(players.some(p=>p.number===number))throw Error('Eine Trikotnummer ist doppelt.');players.push({number,name:m[2]||''})}return players.sort((a,b)=>+a.number-+b.number)}
const teamsViewBeforeColors=teamsView;
teamsView=function(){return teamsViewBeforeColors().replace('<div class="team-list">','<div class="notice">Ohne eigene Farbe: Heimteam Blau, Gastteam Rot. Eigene Farben bleiben für die Mannschaft gespeichert.</div><button class="primary" id="team-csv" style="margin-bottom:20px">↑ Mannschaften importieren</button><div class="team-list">').replace(/<h2>(.*?)<\/h2><button data-editteam="([^"]+)"/g,(all,name,id)=>`<h2><span class="color-dot" style="background:${isColor(team(id)?.color)?team(id).color:'linear-gradient(90deg, '+BLUE+' 50%, '+RED+' 50%)'}"></span> ${name}</h2><button data-editteam="${id}"`)};
function parseCsv(input){const rows=[];let row=[],cell='',quoted=false;const text=input.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0],delimiter=first.includes(';')?';':first.includes('\t')?'\t':',';for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted)quoted=false;else if(!cell)quoted=true;else throw Error('Ungültige Anführungszeichen in der Datei.')}else if(!quoted&&c===delimiter){row.push(cell.trim());cell=''}else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Ein Textfeld in der Datei ist nicht geschlossen.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows}
function parseTeamCsv(text){const rows=parseCsv(text),header=rows.shift()?.map(s=>s.toLowerCase());if(!header||!['mannschaft','nummer','name'].every(k=>header.includes(k)))throw Error('Benötigte Spalten: Mannschaft;Nummer;Name;Farbe (optional).');const get=(r,k)=>r[header.indexOf(k)]||'', groups=new Map();for(const r of rows){const name=get(r,'mannschaft'),n=get(r,'nummer'),color=get(r,'farbe');if(!name||!/^\d{1,2}$/.test(n))throw Error('Jede Zeile benötigt eine Mannschaft und Nummer (0–99).');if(color&&!isColor(color))throw Error('Farbe bitte als Hexwert angeben, z. B. #2563eb.');const key=name.toLocaleLowerCase('de'),item=groups.get(key)||{name,players:[],color:null};const number=String(Number(n));if(item.players.some(p=>p.number===number))throw Error(`Doppelte Nummer ${number} bei ${name}.`);if(color&&item.color&&color.toLowerCase()!==item.color.toLowerCase())throw Error(`Widersprüchliche Farben bei ${name}.`);if(color)item.color=color;item.players.push({number,name:get(r,'name')});groups.set(key,item)}if(!groups.size)throw Error('Die Datei enthält keine Spieler.');return [...groups.values()]}
function teamImportDialog(){modal(`<div class="eyebrow">Feste Rückennummern übernehmen</div><h2>Mannschaften importieren</h2><p class="muted" style="margin:14px 0;line-height:1.6">CSV-Datei auswählen oder Tabelleninhalt einfügen. Dies ist ein allgemeiner Tabellenimport; ein direkter Handball4all-Abruf ist noch nicht angebunden.</p><p class="muted">Spalten: Mannschaft;Nummer;Name;Farbe (optional)</p><input type="file" id="roster-file" accept=".csv,.tsv,.txt,text/csv" aria-label="Mannschaftsdatei" style="width:100%;margin:12px 0"><textarea id="roster-csv" aria-label="Mannschaftsdaten" placeholder="Mannschaft;Nummer;Name;Farbe&#10;TSV Heim;7;Max Beispiel;#2563eb&#10;TSV Heim;12;Alex Beispiel;#2563eb"></textarea><div id="roster-preview"></div><div class="dialog-actions"><button data-close>Abbrechen</button><button id="roster-template">CSV-Vorlage</button><button class="primary" id="check-roster">Vorschau</button></div>`);$('#roster-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2000000){toast('Bitte eine Datei unter 2 MB wählen.');return}$('#roster-csv').value=await f.text();$('#roster-preview').innerHTML=''};$('#roster-template').onclick=()=>download('mannschaft-vorlage.csv','\uFEFFMannschaft;Nummer;Name;Farbe\r\nTSV Heim;7;Max Beispiel;#2563eb\r\nTSV Heim;12;Alex Beispiel;#2563eb\r\nSV Gast;9;Sam Beispiel;#dc3545','text/csv;charset=utf-8');$('#check-roster').onclick=()=>{try{const groups=parseTeamCsv($('#roster-csv').value);$('#roster-preview').innerHTML=`<div class="notice" style="margin-top:12px">${groups.map(t=>`${esc(t.name)}: ${t.players.length} Spieler`).join('<br>')}<p style="margin-top:8px">Neue Mannschaften werden angelegt. Bei gleichem Mannschaftsnamen werden Spieler über die Nummer ergänzt oder aktualisiert. Bestehende andere Nummern und Spieldaten bleiben erhalten.</p><button class="primary" id="apply-roster" style="margin-top:10px">Import übernehmen</button></div>`;$('#apply-roster').onclick=()=>{for(const incoming of groups){const existing=db.teams.find(t=>t.name.toLocaleLowerCase('de')===incoming.name.toLocaleLowerCase('de'));if(existing){for(const p of incoming.players){const old=existing.players.find(x=>x.number===p.number);if(old){if(p.name)old.name=p.name}else existing.players.push(p)}if(incoming.color)existing.color=incoming.color;existing.players.sort((a,b)=>+a.number-+b.number)}else db.teams.push({...incoming,id:uid()})}persist();$('#dialog').close();render();toast('Mannschaften importiert')}}catch(err){toast(err.message)}};$('#roster-csv').oninput=()=>{$('#roster-preview').innerHTML=''}}
const bindBeforeTeamFeatures=bind;
bind=function(){bindBeforeTeamFeatures();if($('#team-csv'))$('#team-csv').onclick=teamImportDialog;const g=game();if(tab!=='live'||!g)return;const color=teamColor(selectedTeam,g);$('.match-workspace').style.setProperty('--team-color',color);$('.match-workspace').style.setProperty('--team-ink',colorText(color));document.querySelectorAll('[data-team]').forEach(b=>{const c=teamColor(b.dataset.team,g);b.style.setProperty('--button-team',c);b.style.setProperty('--button-ink',colorText(c))});const opponent=opposingTeam(g,selectedTeam),current=editId?(Object.hasOwn(draft,'keeper')?draft.keeper:'?'):keeperValue(g,opponent),target=$('.outcome-panel');target.querySelector('div').insertAdjacentHTML('afterend',`<label class="keeper-picker">Torhüter · ${esc(teamName(opponent))}<select id="opponent-keeper">${keeperOptions(opponent,current)}</select></label>`);$('#opponent-keeper').onchange=e=>{if(editId)draft.keeper=e.target.value;else{g.keepers??={};g.keepers[opponent]=e.target.value;persist()}render()};$('.match-timer').insertAdjacentHTML('afterend','<button id="keeper-setup" class="keeper-setup">Torhüter</button>');$('#keeper-setup').onclick=()=>keeperDialog(g);if((!keepersReady(g)&&!editId)||!current){const b=document.querySelector('[data-action="saveShot"]');b.disabled=true;b.title='Bitte zuerst beide Torhüter auswählen.'}const line=$('#path-line');if(line)line.setAttribute('stroke',color);document.querySelector('#arrow path')?.setAttribute('fill',color);$('#path-start')?.setAttribute('stroke',color)};
const clockBeforeKeepers=actions.clock;
actions.clock=()=>{if(!keepersReady(game())){keeperDialog(game());return}clockBeforeKeepers()};
actions.period=()=>{stopClock();game().period=game().period===2?1:2;elapsed=game().period===2?(game().halfMinutes||30)*60:0;game().elapsed=elapsed;persist();render()};
const analysisBeforeKeepers=analysisView;
analysisView=function(){const shots=filtered().filter(s=>s.keeperTeam&&s.keeper&&!['?','empty'].includes(s.keeper));const keys=[...new Set(shots.map(s=>s.keeperTeam+'|'+s.keeper))];return analysisBeforeKeepers()+`<div class="card"><h2>Torhüter in dieser Auswahl</h2><p class="muted" style="margin:12px 0">Fangquote = gehalten / (gehalten + Tore). Pfosten, Fehlwürfe und Blocks werden dafür nicht gezählt.</p><div class="tablewrap"><table><thead><tr><th>Mannschaft</th><th>Torhüter</th><th>Gehalten</th><th>Gegentore</th><th>Fangquote</th></tr></thead><tbody>${keys.map(key=>{const [tid,n]=key.split('|'),a=shots.filter(s=>s.keeperTeam===tid&&s.keeper===n),saved=a.filter(s=>s.result==='Gehalten').length,goals=a.filter(s=>s.result==='Tor').length;return `<tr><td>${esc(teamName(tid))}</td><td>#${esc(n)} ${esc(a[0].keeperName||playerName(tid,n))}</td><td>${saved}</td><td>${goals}</td><td>${saved+goals?Math.round(saved/(saved+goals)*100)+' %':'–'}</td></tr>`}).join('')||'<tr><td colspan="5">Noch keine Würfe mit bekanntem Torhüter erfasst.</td></tr>'}</tbody></table></div></div>`};
render();
